"""Render the human-readable .md companions from the JSON outputs (numbers come only from the JSON)."""
import json, collections
from common import *


def esc(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


def ids(lst, n=6):
    out = []
    for x in (lst or [])[:n]:
        out.append("`%s`" % esc(x if isinstance(x, str) else json.dumps(x, ensure_ascii=False))[:140])
    return ", ".join(out)


def timeline():
    t = jload(OUT + "/timeline.json")
    L = ["# HarmonyGames timeline spine (2024 → clock %s)" % CLOCK_ISO[:10], "",
         "> Generated by `_build/assemble_timeline.py` from `timeline.json`. Listed evidence was re-read from the selected source before the assigned freeze; bracketed dates belong to the records. %d of %d spine events meet the 2-service rule, plus %d storyline beats (2024+) with dated artifacts in 2+ services. Orientation-only summaries require verification." % (t["counts"]["spine_meeting_rule"], t["counts"]["spine_events"], t["counts"]["storyline_beats"]),
         "", "**Prelude (2023):** " + t["_meta"]["prelude_2023"], "",
         "| Date | Category | Event | Services | Evidence (verified id → record date) |", "|---|---|---|---|---|"]
    for e in t["spine"]:
        ev = "; ".join("`%s` (%s)" % (esc(x["id"]), (x.get("when") or "")[:10]) for x in e["evidence"][:6])
        label = ("[orientation only] " if e.get("orientation_only") else "") + e["title"]
        L.append("| %s | %s | %s | %s | %s |" % (e["date"], e["category"], esc(label), ", ".join(e["services"]), ev))
    L += ["", "## How to use", "- Anchor seeded records before the assigned freeze, using activity.json for the selected source. Orientation-only narratives require record-level verification.",
          "- Before writing 'X shipped on D', check the spine event and the warehouse/Slack disagreement notes in coherence_hazards (L14, Q06-Q08).",
          "- Departure rows ('… goes quiet') come from activity.json: do not seed messages from these people after that date.",
          "", "## Storyline beats 2024+ (verified artifacts; YAML summaries are not ground truth)", "", "| Date | Storyline | Beat | Services | First evidence ids |", "|---|---|---|---|---|"]
    for b in t["storyline_beats_2024_plus"]:
        L.append("| %s | %s | %s | %s | %s |" % (b["date"], esc((b["storyline_name"] or b["storyline"])[:70]), esc(b["action"][:110]), ", ".join(b["services"]), ids(b["evidence"], 3)))
    open(OUT + "/timeline.md", "w").write("\n".join(L) + "\n")


def hazards():
    h = jload(OUT + "/coherence_hazards.json")
    L = ["# Coherence hazards already in the HarmonyGames base", "", "> " + h["_meta"]["use"], "> Generated by `_build/assemble_hazards_traps.py`; machine-readable twin: `coherence_hazards.json` (full id lists for Linear/GitHub/Trello/GCal hazards are under `examples`/`all` there).", "",
         "**Checked and clean:**", ""] + ["- " + x for x in h["_meta"]["checked_and_clean"]] + [""]
    names = {"temporal": "Temporal", "semantic_category": "Semantic / category", "cross_service_referential": "Cross-service referential", "quantitative": "Quantitative", "state_lifecycle": "State / lifecycle", "identifier_format": "Identifier / format"}
    for cat, lst in h["categories"].items():
        L += ["## " + names.get(cat, cat), "", "| Id | Service | Hazard | Count | Denominator | Example ids | Keep-out guidance |", "|---|---|---|---|---|---|---|"]
        for x in lst:
            L.append("| %s | %s | %s | %s | %s | %s | %s |" % (x["id"], x["service"], esc(x["title"]), x["count"], esc(x.get("denominator") or ""), ids(x["examples"], 5), esc(x["keep_out_guidance"])))
        L.append("")
    open(OUT + "/coherence_hazards.md", "w").write("\n".join(L) + "\n")


def traps():
    t = jload(OUT + "/trap_catalog.json")
    L = ["# Natural trap catalog", "", "> " + t["_meta"]["use"], "> Generated by `_build/assemble_hazards_traps.py`; twin: `trap_catalog.json`. Identity collisions in depth: `entities.json` (`collisions`).", ""]
    names = {"lookalike_people": "Lookalike people and names", "ticket_series_collision": "Ticket-series and number collisions", "near_duplicate_documents": "Near-duplicate documents and titles",
             "stale_vs_current": "Stale vs current versions", "superseded_claims": "Superseded decisions and overturned conclusions", "bot_noise": "Bot noise", "redaction": "Redacted tokens", "lookalike_containers": "Lookalike containers and renamed products"}
    for kind, lst in t["kinds"].items():
        L += ["## " + names.get(kind, kind), ""]
        for x in lst:
            L += ["### %s — %s" % (x["id"], esc(x["title"])), "", "- **Count:** %s" % x["count"], "- **Risk:** " + esc(x["risk"]), "- **Legitimate use:** " + esc(x["legitimate_use"]),
                  "- **Ids / examples:** " + (ids(x["ids"], 8) if isinstance(x["ids"], list) else "`%s`" % esc(json.dumps(x["ids"], ensure_ascii=False))[:900]), ""]
    open(OUT + "/trap_catalog.md", "w").write("\n".join(L) + "\n")


def cohorts():
    c = jload(OUT + "/cohorts.json")
    L = ["# Natural cohorts (40–500 records)", "", "> " + c["_meta"]["use"], "> " + c["_meta"]["not_cohorts"], "> Generated by `_build/assemble_cohorts.py`; full id lists (when ≤ 500) in `cohorts.json`.", "",
         "## Per-record surfaces and bulk paths by record kind", "", "| Record kind | Per-record surfaces | Bulk call that returns them | Honest per-record calls |", "|---|---|---|---|"]
    seen = set()
    for x in c["cohorts"]:
        k = x["record_kind"]
        if k in seen or "bulk" not in x:
            continue
        seen.add(k)
        L.append("| %s | %s | %s | %s |" % (k, esc("; ".join(x.get("per_record_surfaces", []))), esc(x.get("bulk", "")), esc(x.get("honest_per_record_calls", ""))))
    L += [""]
    by = collections.defaultdict(list)
    for x in c["cohorts"]:
        by[x["service"]].append(x)
    for svc, lst in by.items():
        L += ["## " + svc, "", "| Id | Cohort | Selection rule | Count | Hazards inside | Sample ids |", "|---|---|---|---|---|---|"]
        for x in lst:
            hz = x.get("hazards_inside") or {}
            hs = "; ".join("%s: %s" % (k, v.get("count") if isinstance(v, dict) else v) for k, v in hz.items()) if isinstance(hz, dict) else str(hz)
            L.append("| %s | %s | %s | %s | %s | %s |" % (x["id"], esc(x["name"]), esc(x["selection_rule"]), x["count"], esc(hs[:220]), ids(x.get("sample_ids") or [], 3)))
        L.append("")
    open(OUT + "/cohorts.md", "w").write("\n".join(L) + "\n")


def integrations():
    j = jload(OUT + "/integrations.json")
    L = ["# Integrations and automated mirrors", "", "> " + j["_meta"]["use"], "> Generated by `_build/assemble_integrations_conventions.py`; exact example records (Slack attachment JSON, Gmail headers) are in `integrations.json`.", "",
         "| Id | Source → destination | Integration | Key base rates | Seeding rule |", "|---|---|---|---|---|"]
    def br(b):
        if not isinstance(b, dict):
            return str(b)
        keep = []
        for k, v in b.items():
            if isinstance(v, (int, float, str)) or v is None:
                keep.append("%s=%s" % (k, v))
        return "; ".join(keep)[:300]
    for x in j["integrations"]:
        L.append("| %s | %s → %s | %s | %s | %s |" % (x["id"], x["source"], x["destination"], esc(x["name"]), esc(br(x["base_rates"])), esc(x["seeding_rule"])))
    gh = j["integrations"][0]
    L += ["", "## GitHub app → Slack: coverage per repo", "", "| Repo | PRs | Mirror window | PRs in window | 'opened' mirrored | merged / merge mirrored | PR comments / comment mirrors | reviews / review mirrors |", "|---|---|---|---|---|---|---|---|"]
    for r, v in gh["base_rates"]["per_repo"].items():
        w = v["mirror_window"]
        L.append("| %s | %d | %s | %d | %d | %d / %d | %d / %d | %d / %d |" % (r, v["prs_total"], (w[0][:10] + " → " + w[1][:10]) if w else "not mirrored", v["prs_in_window"], v["prs_with_opened_mirror"], v["merged_in_window"], v["merged_with_merged_mirror"], v["pr_comments_in_window"], v["comment_mirrors"], v["reviews_in_window"], v["review_mirrors"]))
    L += ["", "Copy rates by record type (GitHub record → has a Slack copy):", ""]
    for k, v in gh["base_rates"]["comment_and_review_copy_rates"].items():
        L.append("- `%s`: %d / %d = %s" % (k, v["with_slack_copy"], v["github_records"], v["rate"]))
    L += ["", "Mirror message kinds (threading):", ""]
    for k, v in gh["shape"]["per_kind"].items():
        L.append("- **%s** — %d messages; threaded under the 'opened' parent %.0f%%; thread_broadcast %.0f%%; example `%s`" % (k, v["messages"], 100 * v["threaded_under_opened_parent_share"], 100 * v["thread_broadcast_share"], v["example_id"]))
    L += ["", "## Jenkins jobs in #builds", "", "| Job | Messages | Builds | First | Last | Started→result share | Status mix |", "|---|---|---|---|---|---|---|"]
    for k, v in [x for x in j["integrations"] if x["id"] == "INT-06"][0]["base_rates"]["jobs"].items():
        L.append("| %s | %d | %d | %s | %s | %s | %s |" % (esc(k), v["messages"], v["builds"], v["first"], v["last"], v["started_with_result_share"], esc(json.dumps(v["status"]))))
    L += ["", "## Gmail sample records per automated sender", ""]
    for k, v in j["gmail_samples"].items():
        L.append("- **%s** — `%s` in `%s`: subject `%s`, from `%s`, labels %s" % (k, v["file"], v["mailbox"], esc(v["subject"]), esc(v["from"]), v["labelIds"]))
    open(OUT + "/integrations.md", "w").write("\n".join(L) + "\n")


def conventions():
    c = jload(OUT + "/conventions.json")
    s = c["slack"]
    L = ["# Writing and id conventions for realistic seeding", "", "> " + c["_meta"]["use"], "> Generated by `_build/assemble_integrations_conventions.py`; full tables in `conventions.json`.", "",
         "## Slack", "", "Message length (characters, human messages with text):", "", "| Channel type | n | p10 | p25 | p50 | p75 | p90 | p99 |", "|---|---|---|---|---|---|---|---|"]
    for k, v in s["length_chars_by_channel_type"].items():
        L.append("| %s | %d | %d | %d | %d | %d | %d | %d |" % (k, v["n"], v["p10"], v["p25"], v["p50"], v["p75"], v["p90"], v["p99"]))
    L += ["", "Tone markers (share of messages):", "", "| Type | starts lowercase | all lowercase | ends . ! ? | emoji | question | @mention | URL | multi-line |", "|---|---|---|---|---|---|---|---|---|"]
    for k, v in s["tone_markers_share_by_channel_type"].items():
        L.append("| %s | %s | %s | %s | %s | %s | %s | %s | %s |" % (k, v["lower_start"], v["all_lower"], v["ends_punct"], v["emoji"], v["question"], v["mention"], v["url"], v["multiline"]))
    L += ["", "Examples near the median length (ids):", ""]
    for k, v in s["examples_near_median_by_type"].items():
        for x in v[:3]:
            L.append("- %s `%s` (%d chars): %s" % (k, x["id"], x["len"], esc(x["text"])))
    L += ["", "Per-person working hours (80% of Slack messages fall in this local window; calendar timezone) and style:", "", "| Person | Calendar tz | Core window (local) | Weekend share | Median length | lowercase start | ends with punctuation | messages |", "|---|---|---|---|---|---|---|---|"]
    for em, v in sorted(s["per_person_hours_and_style"].items(), key=lambda kv: -kv[1]["messages"]):
        w = v["slack_core_80pct_window_local"] or {}
        st = v["style"] or {}
        L.append("| %s | %s | %02d:00–%02d:00 (%dh) | %s | %s | %s | %s | %d |" % (em, v["calendar_tz"], w.get("start_hour", 0), w.get("end_hour", 0), w.get("hours", 0), v["weekend_share"], (st.get("len") or {}).get("p50"), st.get("lower_start_share"), st.get("ends_punct_share"), v["messages"]))
    L += ["", "Ids: " + "; ".join("%s = %s" % (k, v) for k, v in s["ids"].items()), "",
          "## Gmail", "", "- Internal human mail (SENT, @harmonygames.co): new text (quote stripped) %s chars; subject %s chars." % (json.dumps({k: c["gmail"]["internal_new_text_len_chars"][k] for k in ("p25", "p50", "p75", "p90")}), json.dumps({k: c["gmail"]["internal_subject_len_chars"][k] for k in ("p25", "p50", "p75")})),
          "- Markers: " + ", ".join("%s %s" % (k, v) for k, v in c["gmail"]["internal_markers_share"].items()), "- Thread sizes: %s" % json.dumps(c["gmail"]["thread_size_dist"]), "- Date formats: %s" % json.dumps(c["gmail"]["date_formats"]),
          "- " + c["gmail"]["line_endings"], "- Ids: " + "; ".join("%s = %s" % (k, v) for k, v in c["gmail"]["ids"].items()), "", "Top automated subject patterns (sender token → pattern, count, example id):", ""]
    for p in c["gmail"]["subject_patterns_top"][:30]:
        L.append("- `%s` — `%s` ×%d (`%s`)" % (p["sender"], esc(p["pattern"]), p["n"], esc(p["example"])[:110]))
    li = c["linear"]
    L += ["", "## Linear", "", "States by team:", ""] + ["- **%s**: %s" % (k, ", ".join("%s %d" % kv for kv in v.items())) for k, v in li["states_by_team"].items()]
    L += ["", "Top labels by team:", ""] + ["- **%s** (%d labels): %s" % (k, li["label_vocab_size"].get(k, 0), ", ".join("%s (%d)" % kv for kv in list(v.items())[:15])) for k, v in li["labels_by_team_top"].items()]
    L += ["", "Title prefixes by team (text before ':', '>', '|', ']' or '-'):", ""] + ["- **%s**: %s" % (k, ", ".join("%s (%d)" % kv for kv in list(v.items())[:10])) for k, v in li["title_prefixes_by_team"].items()]
    L += ["", "- Description length: " + "; ".join("%s p50 %s / p90 %s" % (k, v["p50"], v["p90"]) for k, v in li["description_len_chars"].items()), "- Max issue number: " + json.dumps(li["max_number"]), "- Release codenames: " + li["release_codenames"], "- Ids: " + li["ids"]]
    g = c["github"]
    L += ["", "## GitHub", "", "- PR title patterns: " + json.dumps(g["pr_title_patterns"]), "- Examples: " + "; ".join("%s: %s" % (k, ids([x[1] for x in v], 3)) for k, v in g["pr_title_examples"].items()),
          "- Branch patterns: " + json.dumps(g["branch_patterns"]), "- Branch examples: " + "; ".join("%s: %s" % (k, ids([x[1] for x in v], 3)) for k, v in g["branch_examples"].items()),
          "- Commit first line length: %s; lowercase start %d / %d; merge commits %d; conventional-commit prefix %d; contains a Linear key %d" % (json.dumps({k: g["commit_first_line_len"][k] for k in ("p25", "p50", "p75", "p90")}), g["commit_lower_start"], g["commits"], g["commit_merge_msgs"], g["commit_conventional"], g["commit_with_linear_key"]),
          "- PR bodies empty %d / %d; with CodeRabbit summary %d; review states %s; labels %s" % (g["pr_body_empty"], g["prs"], g["pr_body_has_coderabbit_summary"], json.dumps(g["review_states"]), g["labels"]),
          "- Open→merge hours: %s; changed files: %s" % (json.dumps({k: g["pr_open_to_merge_hours"][k] for k in ("p25", "p50", "p75", "p90")}), json.dumps({k: g["pr_size_changed_files"][k] for k in ("p25", "p50", "p75", "p90")}))]
    t = c["trello"]
    L += ["", "## Trello", "", "- Card names: " + json.dumps(t["card_name_patterns"]) + "; desc length p50 %s" % t["desc_len"].get("p50"), "- Labels: " + ", ".join("%s (%d)" % kv for kv in list(t["labels"].items())[:15]),
          "- Lists: " + "; ".join(list(t["lists"].values())[:48]), "- " + t["ids"]]
    gc_ = c["gcal"]
    L += ["", "## Google Calendar", "", "- Duration minutes: %s; attendees per event: %s; self responseStatus: %s; hangout link share %s" % (json.dumps({k: gc_["duration_min"][k] for k in ("p25", "p50", "p75", "p90")}), json.dumps({k: gc_["attendees_per_event"][k] for k in ("p25", "p50", "p75", "p90")}), json.dumps(gc_["self_response_status"]), gc_["hangout_link_share"]),
          "- Start hour UTC histogram: %s" % gc_["start_hour_utc"], "- Summary patterns: " + ", ".join("%s (%d)" % kv for kv in list(gc_["summary_patterns_top"].items())[:20]), "- Ids: " + json.dumps(gc_["ids"])]
    d = c["docs_sheets_slides_drive"]
    L += ["", "## Drive, Docs, Sheets, Slides", "", "- Doc title families: " + ", ".join("%s (%d)" % kv for kv in list(d["doc_title_families_top"].items())[:15]), "- Doc body length: %s" % json.dumps({k: d["doc_body_len_chars"][k] for k in ("p25", "p50", "p75", "p90")}),
          "- Sheet title families: " + ", ".join("%s (%d)" % kv for kv in list(d["sheet_title_families_top"].items())[:12]), "- Tabs per spreadsheet: %s; declared minus non-empty rows: %s" % (json.dumps({k: d["sheet_tabs_per_file"][k] for k in ("p50", "p90", "max")}), json.dumps({k: d["sheet_declared_vs_nonempty_rows"][k] for k in ("p50", "p90")})),
          "- Slide decks: " + ", ".join("%s (%d)" % kv for kv in list(d["slides_title_families_top"].items())[:10]) + "; pages per deck %s" % json.dumps({k: d["slides_pages_per_deck"][k] for k in ("p50", "p90", "max")}), "- " + d["ids"]]
    cf = c["confluence"]
    L += ["", "## Confluence", "", "- Words per page: %s; labels: %s" % (json.dumps({k: cf["words_per_page"][k] for k in ("min", "p50", "max")}), ", ".join(list(cf["labels"])[:20])), "- Version messages: " + "; ".join("%s: %s" % (k, esc(v[0])[:120]) for k, v in list(cf["version_messages_examples"].items())[:8]), "- " + cf["ids"],
          "", "## Snowflake", "", "- " + c["snowflake"]["row_ids"] + "; " + c["snowflake"]["columns"], ""]
    open(OUT + "/conventions.md", "w").write("\n".join(L) + "\n")


if __name__ == "__main__":
    timeline(); hazards(); traps(); cohorts(); integrations(); conventions()
    print("md ok")
